public void setSizes(Container parent)
   {
      if (sizesSet) return;
      int n = parent.getComponentCount();
      preferredWidth = 0;
      preferredHeight = 0;
      minWidth = 0;
      minHeight = 0;
      maxComponentWidth = 0;
      maxComponentHeight = 0;
      for (int i = 0; i < n; i++)
      {
         Component c = parent.getComponent(i);
