        while (left <= right) {
            int mid = (left + right) /2;
            if (A[mid] == target) return true;
            if (A[left] < A[mid]) {
                if (A[left] <= target && target < A[mid]) right = mid - 1;
                else left = mid + 1;
            } else if (A[left] > A[mid]) {
                if (A[mid] < target && target <= A[right]) left = mid + 1;
                else right = mid - 1;
            } else {
                if (A[left] == A[right]) {
                    ++left; --right;
                } else left = mid + 1;
            }
        }
        return false;
    }

